// =================== Component: ProductSection.tsx ===================

interface ProductSectionProps {
  lang: Language;
  onSelectProduct: (product: ProductItem) => void;
}

interface ProductRowCardProps {
  product: ProductItem;
  index: number;
  lang: Language;
  onSelectProduct: (product: ProductItem) => void;
}

const ProductRowCard: React.FC<ProductRowCardProps> = ({
  product,
  index,
  lang,
  onSelectProduct,
}) => {
  // Alternar lados: Linha 1 foto na esquerda, Linha 2 texto na esquerda (foto na direita), etc.
  const isImageRight = index % 2 === 1;
  const itemNumber = String(index + 1).padStart(2, '0');

  // Fallback seguro caso algum host externo esteja instável
  const [imgSrc, setImgSrc] = useState(product.image);

  const handleImageError = () => {
    if (product.id === 'linha-barra-retangular') {
      setImgSrc(ASSETS.imgBarraOval);
    } else if (product.id === 'sabonetes-liquidos') {
      setImgSrc('/assets/liquid_soap.png');
    }
  };

  return (
    <div
      id={`product-row-${product.id}`}
      onClick={() => onSelectProduct(product)}
      className={`w-full bg-white rounded-3xl border border-[#d9cfbe] hover:border-[#59572D] overflow-hidden shadow-2xs hover:shadow-md transition-all duration-300 p-3 sm:p-4 flex ${
        isImageRight ? 'flex-row-reverse' : 'flex-row'
      } items-center gap-3 sm:gap-4 cursor-pointer group`}
      title={lang === 'pt' ? 'Clique para ver todas as informações do produto' : 'Click to view product details'}
    >
      {/* Bloco da Foto (40-42% da linha) - 100% livre de tags sobrepostas */}
      <div className="w-[40%] sm:w-[42%] shrink-0">
        <div className="relative w-full aspect-square bg-[#FAF6F0] rounded-2xl flex items-center justify-center p-2.5 overflow-hidden border border-[#efe5d7] transition-transform duration-300 group-hover:scale-[1.02]">
          <img
            src={imgSrc}
            alt={product.title}
            onError={handleImageError}
            className="w-full h-full object-contain drop-shadow-2xs"
            loading="lazy"
          />
        </div>
      </div>

      {/* Bloco de Texto & Ação (58-60% da linha) */}
      <div className="w-[60%] sm:w-[58%] flex flex-col justify-between py-0.5">
        <div>
          {/* Categoria da Linha */}
          <div className="flex items-center gap-1.5 mb-1.5 flex-wrap">
            <span
              className="w-1.5 h-1.5 rounded-full shrink-0"
              style={{ backgroundColor: BRAND_COLORS.primary }}
            />
            <span className="text-[9.5px] sm:text-[10.5px] font-bold uppercase tracking-wider text-[#59572D]">
              {product.category}
            </span>
          </div>

          {/* Título Principal */}
          <h3 className="text-xs sm:text-[13.5px] font-bold text-[#4A3612] leading-snug group-hover:text-[#59572D] transition-colors break-normal">
            {product.title}
          </h3>

          {/* Trecho Descritivo */}
          <p className="text-[10px] sm:text-[11px] text-[#4A3612]/80 leading-relaxed line-clamp-2 mt-1 font-normal">
            {product.description}
          </p>

          {/* Destaque de Aromas / Ingredientes em Pílulas sutis */}
          {product.identifiedProducts && product.identifiedProducts.length > 0 && (
            <div className="flex flex-wrap gap-1 mt-2">
              {product.identifiedProducts.slice(0, 3).map((item, pIdx) => (
                <span
                  key={pIdx}
                  className="inline-flex items-center gap-1 text-[8.5px] sm:text-[9.5px] font-medium px-1.5 py-0.5 rounded-md bg-[#FAF6F0] text-[#4A3612] border border-[#e8ded0]"
                >
                  <span
                    className="w-1.5 h-1.5 rounded-full shrink-0"
                    style={{ backgroundColor: item.colorCode }}
                  />
                  <span className="truncate max-w-[85px] sm:max-w-[110px]">{item.name.replace(/Sabonete\s+(de\s+)?/i, '')}</span>
                </span>
              ))}
            </div>
          )}
        </div>

        {/* Botão de Ação / Ver Detalhes (Estilo Explore Product da Imagem 6) */}
        <div className="pt-2.5 mt-1 border-t border-[#F2ECE1]">
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onSelectProduct(product);
            }}
            className="w-full sm:w-auto inline-flex items-center justify-center gap-1.5 py-1.5 px-3 rounded-xl text-[10.5px] sm:text-xs font-bold text-[#F8EFE3] shadow-2xs hover:brightness-105 active:scale-98 transition-all cursor-pointer"
            style={{ backgroundColor: BRAND_COLORS.primary }}
          >
            <Eye className="w-3.5 h-3.5 text-[#F8EFE3]" />
            <span>{lang === 'pt' ? 'Ver Detalhes' : 'Explore Product'}</span>
            <ChevronRight className="w-3 h-3 text-[#F8EFE3]" />
          </button>
        </div>
      </div>
    </div>
  );
};

